require_once __DIR__.'/verificar_sesion.php';if($_SERVER['REQUEST_METHOD']!=='POST'||!csrf_validar($_POST['csrf']??'')){header('Location: mostrar_datos.php');exit;}$db=conexion();$id=(int)($_POST['id']??0);$stmt=$db->prepare('SELECT imagen FROM productos WHERE id=?');$stmt->bind_param('i',$id);$stmt->execute();$fila=$stmt->get_result()->fetch_assoc();$stmt->close();if($fila){$del=$db->prepare('DELETE FROM productos WHERE id=?');$del->bind_param('i',$id);if(!$del->execute()){$error=$del->error;$del->close();$db->close();header('Location: mostrar_datos.php?msg='.urlencode('No se pudo eliminar; puede estar asociado a una venta. '.$error));exit;}$del->close();borrar_imagen($fila['imagen']);}$db->close();header('Location: mostrar_datos.php?msg='.urlencode('Operación finalizada'));exit;?>